import json, os, sys

BASE = "/Users/kristinarash/Library/Caches/sportsci-batch-123"
IDS = ["Q17", "Q18", "Q19", "Q20", "Q21", "Q22", "Q23", "Q24"]

with open(os.path.join(BASE, "taxonomy.json"), encoding="utf-8") as f:
    tax = json.load(f)
with open(os.path.join(BASE, "inputs.json"), encoding="utf-8") as f:
    inputs = {e["id"]: e for e in json.load(f)}

REQUIRED = ["id", "sourceFile", "decision", "exclusionReason", "degradedReason", "doiMissing",
            "identityCheck", "confidence", "studyDesign", "primaryDomain", "domains",
            "audiences", "sports", "populations", "evidenceSummary", "screeningLimitations",
            "synthesisCaution", "paper"]
PAPER_KEYS = ["year", "citation", "doi", "abstract", "tldr", "methods", "findings",
              "limitations", "practicalImplications", "athleteDev", "rtp"]

problems = []

def check_strings(obj, path, qid):
    if isinstance(obj, str):
        if "—" in obj or "–" in obj:
            problems.append(f"{qid}: dash character at {path}")
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            check_strings(v, f"{path}[{i}]", qid)
    elif isinstance(obj, dict):
        for k, v in obj.items():
            check_strings(v, f"{path}.{k}", qid)

for qid in IDS:
    p = os.path.join(BASE, "drafts", f"{qid}.json")
    if not os.path.exists(p):
        problems.append(f"{qid}: draft missing")
        continue
    with open(p, encoding="utf-8") as f:
        try:
            d = json.load(f)
        except json.JSONDecodeError as e:
            problems.append(f"{qid}: invalid JSON: {e}")
            continue
    for k in REQUIRED:
        if k not in d:
            problems.append(f"{qid}: missing key {k}")
    if d.get("id") != qid:
        problems.append(f"{qid}: id mismatch")
    inp = inputs.get(qid)
    if inp is None:
        problems.append(f"{qid}: not in inputs.json")
        continue
    if d.get("sourceFile") != inp["sourceFile"]:
        problems.append(f"{qid}: sourceFile differs from inputs.json")
    if d.get("decision") not in ("INCLUDE", "EXCLUDE", "DEGRADED"):
        problems.append(f"{qid}: bad decision")
    if d.get("confidence") not in ("high", "medium", "low"):
        problems.append(f"{qid}: bad confidence")
    if d.get("studyDesign") not in tax["studyDesigns"]:
        problems.append(f"{qid}: studyDesign not in taxonomy: {d.get('studyDesign')}")
    if d.get("primaryDomain") not in tax["domains"]:
        problems.append(f"{qid}: primaryDomain not in taxonomy")
    if d.get("primaryDomain") not in d.get("domains", []):
        problems.append(f"{qid}: primaryDomain not listed in domains")
    for field, vocab in (("domains", "domains"), ("audiences", "audiences"),
                         ("sports", "sports"), ("populations", "populations")):
        for v in d.get(field, []):
            if v not in tax[vocab]:
                problems.append(f"{qid}: {field} value not in taxonomy: {v}")
    paper = d.get("paper") or {}
    for k in PAPER_KEYS:
        if k not in paper:
            problems.append(f"{qid}: paper missing key {k}")
    if not isinstance(paper.get("year"), int):
        problems.append(f"{qid}: paper.year not an int")
    if d.get("decision") == "INCLUDE":
        want = inp["externalDoi"].lower()
        if paper.get("doi") != want:
            problems.append(f"{qid}: paper.doi {paper.get('doi')} != externalDoi {want}")
        if d.get("doiMissing") is not False:
            problems.append(f"{qid}: doiMissing should be false")
        if d.get("degradedReason"):
            problems.append(f"{qid}: degradedReason should be empty for INCLUDE")
    if not paper.get("doi", "").startswith("10."):
        problems.append(f"{qid}: doi does not start with 10.")
    check_strings(d, "$", qid)

if problems:
    print("PROBLEMS:")
    for p in problems:
        print(" -", p)
    sys.exit(1)
print("All 8 drafts pass the checks.")

